import * as yup from "yup";

// 🟢 1. Login Validation
export const loginSchemaValidation = yup.object().shape({
  email: yup.string().email("Please enter a valid email format (e.g. name@email.com)").required("Email is required"),
  password: yup.string().min(6, "Password must be at least 6 characters").required("Password is required")
});

// 🟢 2. Student Register Validation
export const studentSchemaValidation = yup.object().shape({
  fullName: yup.string().min(3, "Full name must be at least 3 characters").matches(/^[a-zA-Z\s]+$/, "Full name should contain only letters").required("Full name is required"),
  email: yup.string().email("Enter a valid email address").required("Email is required"),
  major: yup.string().required("Please select your major"),
  age: yup.number().typeError("Age must be a number").min(17, "Minimum age is 17").max(45, "Maximum age is 45").required("Age is required"),
  password: yup.string().min(6, "Password must be at least 6 characters").matches(/[A-Z]/, "Password must include at least one uppercase letter").matches(/[0-9]/, "Password must include at least one number").required("Password is required")
});

// 🟢 3. Company Register Validation
export const companySchemaValidation = yup.object().shape({
  companyName: yup.string().min(3, "Company name must be at least 3 characters").required("Company name is required"),
  email: yup.string().email("Enter a valid email address").required("Email is required"),
  industry: yup.string().min(2, "Please enter a valid industry type").required("Industry type is required"),
  location: yup.string().min(2, "Please enter a valid location").required("Location is required"),
  password: yup.string().min(6, "Password must be at least 6 characters").matches(/[A-Z]/, "Password must include at least one uppercase letter").matches(/[0-9]/, "Password must include at least one number").required("Password is required")
});
